#include "../../BaseTest.Bridge.h"

// forward declarations - TS hoists function declarations, C++ does not
void testExtend();
void tbfeCheckExtended(std::any extended, std::any hasSub);

void testExtend()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("regirock") },
    });
    std::any obj1 = ccxt::dict {
        { std::string("a"), 1 },
        { std::string("b"), ccxt::list{1, 2} },
        { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 1 },
    { std::string("test2"), 1 },
}} },
        { std::string("d"), std::any{} },
        { std::string("e"), std::string("not_undefined") },
        { std::string("sub"), ccxt::dict {
            { std::string("a"), 1 },
            { std::string("b"), ccxt::list{1, 2} },
            { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 1 },
    { std::string("test2"), 2 },
}} },
            { std::string("d"), std::any{} },
            { std::string("e"), std::string("not_undefined") },
            { std::string("other1"), std::string("x") },
        } },
        { std::string("other1"), std::string("x") },
    };
    std::any obj2 = ccxt::dict {
        { std::string("a"), 2 },
        { std::string("b"), ccxt::list{3, 4} },
        { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 2 },
    { std::string("test3"), 3 },
}} },
        { std::string("d"), std::string("not_undefined") },
        { std::string("e"), std::any{} },
        { std::string("sub"), ccxt::dict {
            { std::string("a"), 2 },
            { std::string("b"), ccxt::list{3, 4} },
            { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 2 },
    { std::string("test3"), 3 },
}} },
            { std::string("d"), std::string("not_undefined") },
            { std::string("e"), std::any{} },
            { std::string("other2"), std::string("y") },
        } },
        { std::string("other2"), std::string("y") },
    };
    // snapshot originals for mutation checks
    std::any obj1SnapshotA = ::getValue(obj1, std::string("a"));
    std::any obj1SnapshotB0 = ::getValue(::getValue(obj1, std::string("b")), 0);
    std::any obj1SnapshotOther1 = ::getValue(obj1, std::string("other1"));
    std::any obj2SnapshotA = ::getValue(obj2, std::string("a"));
    std::any obj2SnapshotB0 = ::getValue(::getValue(obj2, std::string("b")), 0);
    std::any obj2SnapshotOther2 = ::getValue(obj2, std::string("other2"));
    // --- test 1: basic extend ---
    std::any extended = exchange.extend(obj1, obj2);
    tbfeCheckExtended(extended, true);
    // --- mutation check: obj1 must NOT be mutated ---
    assertTrue(isEqual(::getValue(obj1, std::string("a")), obj1SnapshotA), std::string("obj1.a was mutated after extend"));
    assertTrue(isEqual(::getValue(::getValue(obj1, std::string("b")), 0), obj1SnapshotB0), std::string("obj1.b[0] was mutated after extend"));
    assertTrue(isEqual(::getValue(obj1, std::string("other1")), obj1SnapshotOther1), std::string("obj1['other1'] was mutated after extend"));
    // --- mutation check: obj2 must NOT be mutated ---
    assertTrue(isEqual(::getValue(obj2, std::string("a")), obj2SnapshotA), std::string("obj2.a was mutated after extend"));
    assertTrue(isEqual(::getValue(::getValue(obj2, std::string("b")), 0), obj2SnapshotB0), std::string("obj2.b[0] was mutated after extend"));
    assertTrue(isEqual(::getValue(obj2, std::string("other2")), obj2SnapshotOther2), std::string("obj2['other2'] was mutated after extend"));
    // --- test 2: multi-step extend – apply a third patch on top of the first result ---
    std::any obj3 = ccxt::dict {
        { std::string("a"), 3 },
        { std::string("b"), ccxt::list{5, 6} },
        { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 3 },
    { std::string("test4"), 4 },
}} },
        { std::string("d"), std::string("step3") },
        { std::string("e"), std::string("back_to_string") },
        { std::string("other3"), std::string("z") },
    };
    std::any extended2 = exchange.extend(extended, obj3);
    assertTrue(isEqual(::getValue(extended2, std::string("a")), 3), std::string("step2: a"));
    assertTrue(isEqual(::getValue(::getValue(extended2, std::string("b")), 0), 5), std::string("step2: b[0]"));
    assertTrue(isEqual(::getValue(::getValue(extended2, std::string("b")), 1), 6), std::string("step2: b[1]"));
    assertTrue(isEqual(::getValue(::getValue(::getValue(extended2, std::string("c")), 0), std::string("test1")), 3), std::string("step2: c[0].test1"));
    assertTrue(!isTrue((inOp(::getValue(::getValue(extended2, std::string("c")), 0), std::string("test2")))), std::string("step2: c[0] should not have test2"));
    assertTrue(!isTrue((inOp(::getValue(::getValue(extended2, std::string("c")), 0), std::string("test3")))), std::string("step2: c[0] should not have test3"));
    assertTrue(isEqual(::getValue(::getValue(::getValue(extended2, std::string("c")), 0), std::string("test4")), 4), std::string("step2: c[0].test4"));
    assertTrue(isEqual(::getValue(extended2, std::string("d")), std::string("step3")), std::string("step2: d"));
    assertTrue(isEqual(::getValue(extended2, std::string("e")), std::string("back_to_string")), std::string("step2: e"));
    assertTrue(isEqual(::getValue(extended2, std::string("other1")), std::string("x")), std::string("step2: extended2['other1'] preserved"));
    assertTrue(isEqual(::getValue(extended2, std::string("other2")), std::string("y")), std::string("step2: extended2['other2'] preserved"));
    assertTrue(isEqual(::getValue(extended2, std::string("other3")), std::string("z")), std::string("step2: extended2['other3'] added"));
    // --- mutation check: first result must NOT be mutated by second extend ---
    assertTrue(isEqual(::getValue(extended, std::string("a")), 2), std::string("extended['a'] was mutated by second extend"));
    assertTrue(isEqual(::getValue(::getValue(extended, std::string("b")), 0), 3), std::string("extended['b'][0] was mutated by second extend"));
    assertTrue(!isTrue((inOp(extended, std::string("other3")))), std::string("extended['other3'] should not exist after second extend"));
    // --- test 3: four-step chained extend on same base object ---
    std::any base = ccxt::dict {
        { std::string("x"), 0 },
        { std::string("keep"), std::string("yes") },
    };
    std::any patch1 = ccxt::dict {
        { std::string("x"), 1 },
        { std::string("p1"), true },
    };
    std::any patch2 = ccxt::dict {
        { std::string("x"), 2 },
        { std::string("p2"), true },
    };
    std::any patch3 = ccxt::dict {
        { std::string("x"), 3 },
        { std::string("p3"), true },
    };
    std::any r1 = exchange.extend(base, patch1);
    std::any r2 = exchange.extend(r1, patch2);
    std::any r3 = exchange.extend(r2, patch3);
    assertTrue(isEqual(::getValue(r3, std::string("x")), 3), std::string("chain: r3['x'] should be 3 after 3 patches"));
    assertTrue(isEqual(::getValue(r3, std::string("keep")), std::string("yes")), std::string("chain: r3['keep'] should be preserved"));
    assertTrue(isEqual(::getValue(r3, std::string("p1")), true), std::string("chain: r3['p1'] should be present"));
    assertTrue(isEqual(::getValue(r3, std::string("p2")), true), std::string("chain: r3['p2'] should be present"));
    assertTrue(isEqual(::getValue(r3, std::string("p3")), true), std::string("chain: r3['p3'] should be present"));
    // --- mutation check: each intermediate must be unaffected ---
    assertTrue(isEqual(::getValue(base, std::string("x")), 0), std::string("base['x'] was mutated during chain"));
    assertTrue(isEqual(::getValue(r1, std::string("x")), 1), std::string("r1['x'] was mutated during chain"));
    assertTrue(isEqual(::getValue(r2, std::string("x")), 2), std::string("r2['x'] was mutated during chain"));
    assertTrue(!isTrue((inOp(r1, std::string("p3")))), std::string("r1['p3'] leaked into r1"));
    assertTrue(!isTrue((inOp(base, std::string("p2")))), std::string("base['p2'] leaked into base"));
    // --- test 4: extend with undefined values does NOT overwrite existing keys ---
    std::any withValues = ccxt::dict {
        { std::string("keep1"), std::string("A") },
        { std::string("keep2"), std::string("B") },
    };
    std::any withUndefs = ccxt::dict {
        { std::string("keep1"), std::any{} },
        { std::string("keep2"), std::any{} },
        { std::string("newKey"), std::string("C") },
    };
    std::any extUndef = exchange.extend(withValues, withUndefs);
    // extend() merges ALL keys (including undefined ones), so undefined wins over previous value
    assertTrue(isEqual(::getValue(extUndef, std::string("keep1")), std::any{}), std::string("extend: extUndef['keep1'] should be undefined"));
    assertTrue(isEqual(::getValue(extUndef, std::string("keep2")), std::any{}), std::string("extend: extUndef['keep2'] should be undefined"));
    assertTrue(isEqual(::getValue(extUndef, std::string("newKey")), std::string("C")), std::string("extend: extUndef['newKey'] should be added"));
    // original must not be touched
    assertTrue(isEqual(::getValue(withValues, std::string("keep1")), std::string("A")), std::string("withValues['keep1'] was mutated"));
    assertTrue(isEqual(::getValue(withValues, std::string("keep2")), std::string("B")), std::string("withValues['keep2'] was mutated"));
}
void tbfeCheckExtended(std::any extended, std::any hasSub)
{
    assertTrue(isEqual(::getValue(extended, std::string("a")), 2));
    assertTrue(isEqual(::getValue(::getValue(extended, std::string("b")), 0), 3));
    assertTrue(isEqual(::getValue(::getValue(extended, std::string("b")), 1), 4));
    assertTrue(isEqual(::getValue(::getValue(::getValue(extended, std::string("c")), 0), std::string("test1")), 2));
    assertTrue(!isTrue((inOp(::getValue(::getValue(extended, std::string("c")), 0), std::string("test2")))));
    assertTrue(isEqual(::getValue(::getValue(::getValue(extended, std::string("c")), 0), std::string("test3")), 3));
    assertTrue(isEqual(::getValue(extended, std::string("d")), std::string("not_undefined")));
    assertTrue(isEqual(::getValue(extended, std::string("e")), std::any{}));
    assertTrue(isEqual(::getValue(extended, std::string("other1")), std::string("x")));
    assertTrue(isEqual(::getValue(extended, std::string("other2")), std::string("y")));
    if (isTrue(hasSub))
    {
        assertTrue(inOp(extended, std::string("sub")));
    }
}

